// Applies the EduHub changes to a copy of the project, without needing to unzip anything.
// Usage: put this file inside the project folder (next to package.json) and run:   node apply-changes.mjs
import fs from "node:fs";
import path from "node:path";

if (!fs.existsSync("package.json") || !JSON.parse(fs.readFileSync("package.json", "utf8")).name?.includes("eduhub")) {
  console.error("Run this inside the EduHub project folder (the one that contains package.json).");
  process.exit(1);
}
const FILES = {".env.example": "", "README.md": "", "docs/ARCHITECTURE.md": "", "docs/DEPLOY-VERCEL.md": "", "docs/PRD.md": "", "drizzle/0002_rate_limits.sql": "Q1JFQVRFIFRBQkxFICJyYXRlX2xpbWl0cyIgKAoJImtleSIgdGV4dCBQUklNQVJZIEtFWSBOT1QgTlVMTCwKCSJjb3VudCIgaW50ZWdlciBOT1QgTlVMTCwKCSJyZXNldF9hdCIgdGltZXN0YW1wIHdpdGggdGltZSB6b25lIE5PVCBOVUxMCik7Cg==", "drizzle/meta/0002_snapshot.json": "", "drizzle/meta/_journal.json": "", "messages/ar.json": "", "messages/en.json": "", "package-lock.json": "", "package.json": "", "scripts/migrate.mjs": "", "scripts/smoke.mjs": "", "src/app/api/v1/[[...route]]/route.ts": "", "src/components/auth-forms.tsx": "", "src/lib/api.ts": "", "src/server/accounts.ts": "", "src/server/api.ts": "", "src/server/config.ts": "", "src/server/db/index.ts": "", "src/server/db/schema.ts": "", "src/server/email.ts": "", "src/server/ratelimit.ts": "", "src/server/session.ts": "", "src/server/storage.ts": "", "vercel.json": "ewogICIkc2NoZW1hIjogImh0dHBzOi8vb3BlbmFwaS52ZXJjZWwuc2gvdmVyY2VsLmpzb24iLAogICJmcmFtZXdvcmsiOiAibmV4dGpzIiwKICAiYnVpbGRDb21tYW5kIjogIm5wbSBydW4gZGI6bWlncmF0ZSAmJiBucG0gcnVuIGJ1aWxkIgp9Cg=="};
const DELETED = ["src/app/(auth)/verify-email/page.tsx"];

let written = 0;
for (const [file, b64] of Object.entries(FILES)) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, Buffer.from(b64, "base64"));
  written++;
}
let removed = 0;
for (const file of DELETED) {
  if (fs.existsSync(file)) {
    fs.rmSync(file);
    removed++;
  }
  const dir = path.dirname(file);
  if (fs.existsSync(dir) && fs.readdirSync(dir).length === 0) fs.rmdirSync(dir);
}
console.log(`Done: ${written} files written, ${removed} removed.`);
console.log("Next: npm install   then   git add -A && git commit -m \"Vercel fixes, registration without email code\" && git push");
